import numpy as np
from collections import deque
g = np.array(grid)
H,W = g.shape
# global flood of 0s from border (4-conn)
reach = np.zeros((H,W),bool)
q = deque()
for i in range(H):
    for j in (0,W-1):
        if g[i,j]==0: reach[i,j]=True; q.append((i,j))
for j in range(W):
    for i in (0,H-1):
        if g[i,j]==0: reach[i,j]=True; q.append((i,j))
while q:
    i,j=q.popleft()
    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        a,b=i+di,j+dj
        if 0<=a<H and 0<=b<W and g[a,b]==0 and not reach[a,b]:
            reach[a,b]=True;q.append((a,b))
cavity = (g==0)&~reach
print("cavity cells:", cavity.sum())

# wall components (8-conn), qualifying if 4-adjacent to any cavity cell
lab = np.zeros((H,W),int)
comps=[]
for i in range(H):
    for j in range(W):
        if g[i,j]==1 and lab[i,j]==0:
            cid=len(comps)+1; cells=[(i,j)]; lab[i,j]=cid; qq=deque([(i,j)])
            while qq:
                a,b=qq.popleft()
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        c,d=a+da,b+db
                        if 0<=c<H and 0<=d<W and g[c,d]==1 and lab[c,d]==0:
                            lab[c,d]=cid;cells.append((c,d));qq.append((c,d))
            comps.append(cells)
qual=set()
for cid,cells in enumerate(comps,1):
    touches=any(cavity[a+da,b+db] for a,b in cells for da,db in ((1,0),(-1,0),(0,1),(0,-1))
                if 0<=a+da<H and 0<=b+db<W)
    if touches: qual.add(cid)
print("qualifying comps:", [(cid,len(comps[cid-1])) for cid in qual])

out=g.copy()
# 3: cavity cells 4-adjacent to wall of qualifying comp
for i in range(H):
    for j in range(W):
        if cavity[i,j]:
            if any(0<=i+da<H and 0<=j+db<W and g[i+da,j+db]==1 and lab[i+da,j+db] in qual
                   for da,db in ((1,0),(-1,0),(0,1),(0,-1))):
                out[i,j]=3
# 2: border-reached cells 8-adjacent to qualifying wall
for i in range(H):
    for j in range(W):
        if g[i,j]==0 and reach[i,j]:
            if any(0<=i+da<H and 0<=j+db<W and g[i+da,j+db]==1 and lab[i+da,j+db] in qual
                   for da in(-1,0,1) for db in(-1,0,1) if (da,db)!=(0,0)):
                out[i,j]=2
for r in out: print(''.join(str(c) if c else '.' for c in r))

alt = out.copy()
# 3 = cavity cells 8-adjacent to a qualifying wall
for i in range(H):
    for j in range(W):
        if cavity[i,j] and out[i,j]==0:
            if any(0<=i+da<H and 0<=j+db<W and g[i+da,j+db]==1 and lab[i+da,j+db] in qual
                   for da in(-1,0,1) for db in(-1,0,1) if (da,db)!=(0,0)):
                alt[i,j]=3
diff = [(i,j,out[i,j],alt[i,j]) for i in range(H) for j in range(W) if out[i,j]!=alt[i,j]]
print(diff)
rows2 = [[int(c) for c in r] for r in alt]
assert all(len(r)==30 for r in rows2) and len(rows2)==30
